def compute(vars):
    numerator = vars["v1"]
    denominator = vars["v2"]

    if denominator == 0:
        return None

    ratio = numerator / denominator
    percentage = round(ratio * 100, 3)

    return {
        "value": percentage,
        "trace": {
            "numerator": numerator,
            "denominator": denominator,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }

def compute(vars):
    high = vars["v1"]
    low = vars["v2"]
    average = (high + low) / 2
    return {
        "value": round(average, 3),
        "trace": {
            "high_price": high,
            "low_price": low,
            "average": average,
            "output_meta": {
                "currency": "$",
                "scale": None,
                "unit": "stock price"
            }
        }
    }

def compute(vars):
    cash = vars["v1"]
    total = vars["v2"]

    if total == 0:
        return None

    portion_percent = (cash / total) * 100
    result = round(portion_percent)

    return {
        "value": result,
        "trace": {
            "cash_portion": cash,
            "total_purchase_price": total,
            "portion_percent": portion_percent,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }

def compute(vars):
    backlog = vars["v1"]
    fixed_price_percent = vars["v2"]
    fixed_price_backlog = backlog * fixed_price_percent * 0.01

    return {
        "value": round(fixed_price_backlog, 3),
        "trace": {
            "contracted_backlog": backlog,
            "fixed_price_percent": fixed_price_percent,
            "fixed_price_backlog": round(fixed_price_backlog, 3),
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "amount"
            }
        }
    }

